export interface GeoPoint {
  lat: number;
  lng: number;
}

export interface RideRequest {
  id: string;
  riderId: string;
  pickup: GeoPoint;
  vehicleClass: "standard" | "xl" | "premium";
  requestedAt: number;
}

export interface DriverCandidate {
  driverId: string;
  location: GeoPoint;
  vehicleClass: RideRequest["vehicleClass"];
  rating: number;
  lastTripEndedAt: number | null;
}

export type DispatchDecision =
  | { kind: "assigned"; driverId: string; etaSeconds: number }
  | { kind: "no_drivers"; searchedRadiusKm: number }
  | { kind: "deferred"; retryAfterMs: number };

export interface DriverLocator {
  findNearby(center: GeoPoint, radiusKm: number): Promise<readonly DriverCandidate[]>;
}

export interface MatchingStrategy {
  choose(request: RideRequest, candidates: readonly DriverCandidate[]): DriverCandidate | null;
}

export interface EtaEstimator {
  etaSeconds(from: GeoPoint, to: GeoPoint): number;
}

export interface Clock {
  now(): number;
}

import {
  Clock, DispatchDecision, DriverCandidate, DriverLocator,
  EtaEstimator, MatchingStrategy, RideRequest,
} from "./types";

export interface DispatcherOptions {
  radiiKm: readonly number[];
  maxRequestAgeMs: number;
  deferMs: number;
}

export class Dispatcher {
  constructor(
    private readonly locator: DriverLocator,
    private readonly strategy: MatchingStrategy,
    private readonly eta: EtaEstimator,
    private readonly clock: Clock,
    private readonly opts: DispatcherOptions,
  ) {
    if (opts.radiiKm.length === 0) {
      throw new Error("at least one search radius is required");
    }
  }

  async dispatch(request: RideRequest): Promise<DispatchDecision> {
    let lastRadius = 0;
    for (const radius of this.opts.radiiKm) {
      lastRadius = radius;
      const nearby = await this.locator.findNearby(request.pickup, radius);
      const eligible = nearby.filter((c) => c.vehicleClass === request.vehicleClass);
      const chosen = this.strategy.choose(request, eligible);
      if (chosen !== null) {
        return {
          kind: "assigned",
          driverId: chosen.driverId,
          etaSeconds: this.eta.etaSeconds(chosen.location, request.pickup),
        };
      }
    }
    const age = this.clock.now() - request.requestedAt;
    if (age < this.opts.maxRequestAgeMs) {
      return { kind: "deferred", retryAfterMs: this.opts.deferMs };
    }
    return { kind: "no_drivers", searchedRadiusKm: lastRadius };
  }
}

export function describe(decision: DispatchDecision): string {
  switch (decision.kind) {
    case "assigned":
      return `driver ${decision.driverId} arriving in ${Math.round(decision.etaSeconds / 60)} min`;
    case "no_drivers":
      return `no drivers within ${decision.searchedRadiusKm} km`;
    case "deferred":
      return `retrying in ${decision.retryAfterMs} ms`;
    default: {
      const unreachable: never = decision;
      throw new Error(`unhandled decision ${JSON.stringify(unreachable)}`);
    }
  }
}

import { Clock, DriverCandidate, EtaEstimator, MatchingStrategy, RideRequest } from "./types";

export class NearestIdleStrategy implements MatchingStrategy {
  constructor(
    private readonly eta: EtaEstimator,
    private readonly clock: Clock,
    private readonly minIdleMs: number,
  ) {}

  choose(request: RideRequest, candidates: readonly DriverCandidate[]): DriverCandidate | null {
    const now = this.clock.now();
    let best: DriverCandidate | null = null;
    let bestEta = Number.POSITIVE_INFINITY;
    for (const c of candidates) {
      const idleFor = c.lastTripEndedAt === null ? Number.POSITIVE_INFINITY : now - c.lastTripEndedAt;
      if (idleFor < this.minIdleMs) continue;
      const eta = this.eta.etaSeconds(c.location, request.pickup);
      if (eta < bestEta || (eta === bestEta && best !== null && c.rating > best.rating)) {
        best = c;
        bestEta = eta;
      }
    }
    return best;
  }
}
